SELECT practice_records.date, practice_records.type AS 类型, practice_records.duration AS 时长_秒, practice_records.notes AS 觉察内容, practice_records.breakthrough AS 突破, practice_records.created_at AS 创建时间, practice_records.updated_at AS 更新时间, COALESCE(cardinality(practice_records.photos), 0) AS 照片数 FROM practice_records JOIN auth.users ON auth.users.id = practice_records.user_id WHERE auth.users.email = 'didosheng@163.com' AND practice_records.deleted_at IS NULL ORDER BY practice_records.date DESC;
